55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const ALIKE_ITEMS_PER_BLOCK = 3;
68	const BLOCK_BASE_PREMIUM = 60;
69	
70	const basePremiumForAlikeItems = (type: string, count: number): number =>
71	  count === ALIKE_ITEMS_PER_BLOCK
72	    ? BLOCK_BASE_PREMIUM
73	    : count * BASE_PREMIUMS[type];
74	
75	const countByType = (items: Item[]): Map<string, number> =>
76	  items.reduce(
77	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
78	    new Map<string, number>(),
79	  );
80	
81	const policyBasePremium = (items: Item[]): number =>
82	  [...countByType(items)].reduce(
83	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
84	    0,
85	  );
86	
87	const CURSE_SURCHARGE_RATE = 0.5;
88	
89	const itemSurcharges = (item: Item): number =>
90	  item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0;
91	
92	const quotePremium = (items: Item[]): number => {
93	  const policyBase = policyBasePremium(items);
94	  const riskSurcharges = items.reduce(
95	    (total, item) => total + itemSurcharges(item),
96	    0,
97	  );
98	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
99	  return Math.ceil(
100	    policyBase + riskSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
101	  );
102	};
103	
104	const runStep = (step: Step): StepResult => ({
105	  premium: quotePremium((step as QuoteStep).items),
106	});
107	
108	export const runScenario = (scenario: Scenario): ScenarioResult => ({
109	  results: scenario.steps.map(runStep),
110	});
